/**
 * Builds the per-frame motor layout table the Servo Setup page's motor
 * mapping section reads.
 *
 *   npm run build:motor-layouts
 *
 * Sources of truth, and nothing else
 * ----------------------------------
 * 1. `AP_Motors_test.json` — generated by ArduPilot's own AP_Motors test
 *    harness straight from the motor mixer: every matrix frame's motor
 *    numbers, spin and roll/pitch factors.
 * 2. `AP_Motors_display.json` — ArduPilot's hand-maintained overrides for
 *    drawing those frames (adjusted positions for V/V-tail/A-tail etc., the
 *    Tri tail servo, frames the test harness doesn't emit, and which types
 *    are just the class default).
 * 3. ArduPilot's official diagrams, kept in `data/frames/` as build input
 *    only (the app draws every frame itself, from this table). They're the
 *    only source for which motor of a coaxial pair is on top, and every
 *    layout written here is checked against them.
 *
 * Both JSON files live in the ardupilot_wiki repo and are fetched fresh. Any
 * frame whose motors, spin, position, cant or frame lines disagree with its
 * official diagram fails the build instead of being written, so the table
 * can't drift from ArduPilot's own drawings.
 *
 * Anything these sources don't settle is listed under "Ambiguities" in
 * src/lib/frames/motorLayouts.ts rather than guessed at here.
 */
import {readFileSync, readdirSync, writeFileSync, mkdirSync} from "node:fs";
import {join} from "node:path";
import {fileURLToPath} from "node:url";

const ROOT = fileURLToPath(new URL("..", import.meta.url));
const FRAMES_DIR = join(ROOT, "data", "frames");
const OUT = join(ROOT, "src", "lib", "frames", "motorLayouts.json");
const WIKI = "https://raw.githubusercontent.com/ArduPilot/ardupilot_wiki/master/scripts/motor_diagram_data";

/** Classes whose every FRAME_TYPE falls back to the class default layout: Y6
 * and Tri (the test harness prints "default" for all but a named few), and
 * Single/Coax (their mixers never read FRAME_TYPE). */
const DEFAULT_TYPE_CLASSES = new Set([5, 7, 8, 9]);

async function fetchJson(name) {
    const response = await fetch(`${WIKI}/${name}`);
    if (!response.ok) {
        throw new Error(`could not fetch ${name} (${response.status})`);
    }
    return response.json();
}

/** class → type → official image, from ArduPilot's own file naming
 * (`m_<class>_<type>_<name>.svg`). Deca's one image covers types 1 and 14,
 * which ArduPilot draws as the same frame. */
function frameImages() {
    const images = new Map();
    for (const file of readdirSync(FRAMES_DIR)) {
        const match = /^m_(\d+)_(\d+)_.*\.svg$/.exec(file);
        if (!match) continue;
        const cls = Number(match[1]);
        if (!images.has(cls)) images.set(cls, new Map());
        images.get(cls).set(Number(match[2]), file);
    }
    images.get(14)?.set(14, images.get(14).get(1));
    return images;
}

/** Motor number → {position, spin, layer} as drawn in one bundled diagram.
 * The diagrams put stacked motors in `layer-*-top` / `layer-*-bottom` groups
 * and everything else outside them. */
function parseDiagram(file) {
    const svg = readFileSync(join(FRAMES_DIR, file), "utf8");
    const body = svg.slice(svg.indexOf("</defs>"));
    const section = (from, to) => body.slice(body.indexOf(`id="${from}"`), body.indexOf(`id="${to}"`));

    function byLayer(chunk, pattern) {
        const found = [];
        let rest = chunk;
        // `(?<!\/)>` skips the diagrams' empty self-closing layer groups, which
        // would otherwise swallow whatever follows them as their "contents".
        for (const layer of chunk.matchAll(/<g id="layer-(?:motors|numbers)-(top|middle|bottom)"[^>]*?(?<!\/)>([\s\S]*?)<\/g>/g)) {
            for (const m of layer[2].matchAll(pattern)) found.push({layer: layer[1], m});
            rest = rest.replace(layer[2], "");
        }
        for (const m of rest.matchAll(pattern)) found.push({layer: "flat", m});
        return found;
    }

    const uses = byLayer(section("layer-motors", "layer-motor-numbers"), /<use x="([^"]+)" y="([^"]+)" xlink:href="#([^"]+)"(?: style="transform: rotate3d\((-?\d+), (-?\d+), 0, 45deg\)")?/g)
        .map(({layer, m}) => ({layer, x: Number(m[1]), y: Number(m[2]), kind: m[3], cant: m[4] ? [Number(m[4]), Number(m[5])] : undefined}));
    const numbers = byLayer(section("layer-motor-numbers", "layer-motor-letters"), /<text x="([^"]+)" y="([^"]+)"[^>]*>([^<]+)<\/text>/g)
        .map(({layer, m}) => ({layer, x: Number(m[1]), y: Number(m[2]), label: m[3].trim()}));

    const near = (a, b) => Math.abs(a.x - b.x) < 1 && Math.abs(a.y - b.y) < 1;
    return new Map(numbers.map((n) => {
        const use = uses.find((u) => u.layer === n.layer && near(u, n)) ?? uses.find((u) => near(u, n));
        const kind = use?.kind ?? "";
        const spin = kind.startsWith("CCW") ? "CCW" : kind.startsWith("CW") ? "CW" : kind.startsWith("NYT") ? "Either" : kind.startsWith("tail-servo") ? "servo" : "?";
        // SVG y grows downward; flip so +y is the nose, same as the JSON's pitch.
        return [n.label, {x: n.x, y: -n.y, spin, layer: n.layer, cant: use?.cant}];
    }));
}

/** Every frame line an official diagram draws, flat or in the tilted
 * coaxial layer, in the diagram's own SVG units. The 3D tilt is a CSS
 * transform on the group, so the coordinates underneath are top-down. */
function parseFrameLines(file) {
    const svg = readFileSync(join(FRAMES_DIR, file), "utf8");
    const groups = [
        /<g id="layer-frame"[^>]*>([\s\S]*?)<\/g>/.exec(svg)?.[1] ?? "",
        /<g id="layer-frame-3d"[^>]*?(?<!\/)>([\s\S]*?)<\/g>/.exec(svg)?.[1] ?? "",
    ];
    return groups.flatMap((g) => [...g.matchAll(/<line x1="([^"]+)" y1="([^"]+)" x2="([^"]+)" y2="([^"]+)"/g)].map((m) => m.slice(1, 5).map(Number)));
}

/** FrameLines come as [roll1, pitch1, roll2, pitch2]; ours are [x1, y1, x2,
 * y2] in the same space as motor positions (x = -roll, y = pitch). */
function toFrameLines(lines) {
    return lines?.map(([r1, p1, r2, p2]) => [round(-r1), round(p1), round(-r2), round(p2)]);
}

/**
 * V-tail and A-tail tail rotors are canted, which the official diagrams show
 * by tilting them 45° in 3D about a diagonal axis. Same rule as ArduPilot's
 * `handle_av_tails()` in build_motor_diagrams.py, returned as the axis in SVG
 * space (+y down) so the renderer can foreshorten the rotor top-down instead.
 */
function cantAxis(typeName, x, y) {
    const name = typeName.toLowerCase();
    if (!name.includes("tail") || y >= 0) return undefined; // front rotors aren't canted
    const vTail = name.includes("v");
    const xs = x < 0 && !vTail ? -1 : 1;
    const ys = x < 0 && vTail ? 1 : !vTail ? 1 : -1;
    return [xs, ys];
}

function normalizeSpin(rotation) {
    if (rotation === "?" || rotation === "tail-servo") return "Either";
    return rotation.replace("-normal", "");
}

function round(n) {
    return Math.round(n * 1000) / 1000;
}

const [test, display] = await Promise.all([fetchJson("AP_Motors_test.json"), fetchJson("AP_Motors_display.json")]);

const layouts = new Map();
function put(cls, type, typeName, motors, source) {
    const frameLines = toFrameLines(display[String(cls)]?.[String(type)]?.FrameLines);
    for (const m of motors) {
        const cant = cantAxis(typeName, m.x, m.y);
        if (cant) m.cant = cant;
    }
    layouts.set(`${cls}:${type}`, {cls, type, typeName, source, motors, ...(frameLines ? {frameLines} : {})});
}

for (const layout of test.layouts) {
    const override = display[String(layout.Class)]?.[String(layout.Type)];
    if (override?.Skip) continue;
    const positions = override?.motors ?? layout.motors;
    const motors = layout.motors.map((m) => {
        const p = positions.find((d) => d.Number === m.Number) ?? m;
        return {number: m.Number, kind: "motor", x: round(-p.Roll), y: round(p.Pitch), spin: normalizeSpin(m.Rotation), testOrder: m.TestOrder};
    });
    put(layout.Class, layout.Type, override?.TypeName || layout.TypeName, motors, "AP_Motors_test.json");
}

// Frames the test harness doesn't emit, or emits without the tail servo.
for (const layout of display.layouts) {
    const numeric = layout.motors?.every((m) => typeof m.Number === "number");
    if (!numeric || ![1, 7].includes(layout.Class)) continue; // BiCopter's L/R and the co-rotating demo aren't MotorN frames
    // A per-class override's motor vectors win over the appended layout's:
    // they're what the official diagram was drawn from (Tri's appended entry
    // puts the tail servo on the opposite side of the one in its diagram).
    const positions = display[String(layout.Class)]?.[String(layout.Type)]?.motors ?? layout.motors;
    const motors = layout.motors.map((m) => {
        const p = positions.find((d) => d.Number === m.Number) ?? m;
        const servo = m.Rotation === "tail-servo" || (layout.Class === 7 && m.Number === 7);
        return {
            number: m.Number,
            kind: servo ? "servo" : "motor",
            x: round(-p.Roll),
            y: round(p.Pitch),
            spin: servo ? null : normalizeSpin(m.Rotation),
            testOrder: m.TestOrder,
        };
    });
    put(layout.Class, layout.Type, layout.TypeName, motors, "AP_Motors_display.json");
}

// The test harness prints "X/CW_X" for Deca types 1 and 14 and the display
// file skips 14 as "no diagram needed" — the same layout under both values.
if (layouts.has("14:1") && !layouts.has("14:14")) {
    put(14, 14, "X (CLOCKWISE)", layouts.get("14:1").motors, "AP_Motors_test.json");
}

/*
 * SingleCopter and CoaxCopter aren't matrix frames, so neither JSON has them.
 * They come from ArduPilot's source instead (libraries/AP_Motors):
 * - Motor1-4 are the flap servos. AP_MotorsSingle.cpp names them in its mixer
 *   comments — front, right, rear, left — mixing +roll, +pitch, -roll, -pitch.
 *   AP_MotorsCoax.cpp's mixer is the same four terms in the same order, with
 *   no comments; the positions are carried over from Single on that basis.
 * - Single drives Motor5 and Motor6 with the same thrust: one main motor, on
 *   whichever of the two outputs it's wired to.
 * - Coax drives Motor5 from `_thrust_yt_ccw` and Motor6 from `_thrust_yt_cw`,
 *   so 5 spins CCW and 6 CW. Which of the two is on top isn't stated.
 * - Both frames' motor test runs 1-6 in number order.
 */
const FIN_REACH = 0.62;
const fins = [
    [1, "Front fin", 0, FIN_REACH],
    [2, "Right fin", FIN_REACH, 0],
    [3, "Rear fin", 0, -FIN_REACH],
    [4, "Left fin", -FIN_REACH, 0],
].map(([number, name, x, y]) => ({number, kind: "servo", name, x, y, spin: null, testOrder: number}));
const finLines = fins.map((f) => [0, 0, f.x, f.y]);
layouts.set("8:0", {
    cls: 8,
    type: 0,
    typeName: "",
    source: "AP_MotorsSingle.cpp",
    frameLines: finLines,
    motors: [
        ...fins,
        {number: 5, kind: "motor", name: "Main motor", x: 0, y: 0, spin: "Either", testOrder: 5},
        {number: 6, kind: "motor", name: "Main motor", x: 0, y: 0, spin: "Either", testOrder: 6, sameAs: 5},
    ],
});
layouts.set("9:0", {
    cls: 9,
    type: 0,
    typeName: "",
    source: "AP_MotorsCoax.cpp",
    frameLines: finLines,
    motors: [
        ...fins.map((f) => ({...f})),
        {number: 5, kind: "motor", name: "Coaxial motor", x: 0, y: 0, spin: "CCW", testOrder: 5},
        {number: 6, kind: "motor", name: "Coaxial motor", x: 0, y: 0, spin: "CW", testOrder: 6},
    ],
});

// Check every layout against the diagram Frame Setup shows for it, and take
// the top/bottom order of stacked pairs from that diagram.
const images = frameImages();
const failures = [];
let checked = 0;
for (const layout of layouts.values()) {
    const file = images.get(layout.cls)?.get(layout.type);
    if (!file) continue;
    checked++;
    const drawn = parseDiagram(file);
    const reach = (points) => Math.max(...points.map((p) => Math.hypot(p.x, p.y)));
    const drawnReach = reach([...drawn.values()].filter((d) => d.spin !== "servo"));
    const ourReach = reach(layout.motors.filter((m) => m.kind === "motor"));

    const ours = new Set(layout.motors.map((m) => String(m.number)));
    for (const label of drawn.keys()) if (!ours.has(label)) failures.push(`${file}: draws motor ${label}, layout has none`);
    for (const m of layout.motors) {
        const d = drawn.get(String(m.number));
        if (!d) {
            failures.push(`${file}: layout has motor ${m.number}, diagram doesn't`);
            continue;
        }
        const angle = (x, y) => (Math.atan2(x, y) * 180) / Math.PI;
        const turn = Math.abs(((angle(m.x, m.y) - angle(d.x, d.y) + 540) % 360) - 180);
        if (Math.hypot(d.x, d.y) / drawnReach > 0.1 && turn > 6) failures.push(`${file}: motor ${m.number} is ${turn.toFixed(0)}° off`);
        if (Math.abs(Math.hypot(m.x, m.y) / ourReach - Math.hypot(d.x, d.y) / drawnReach) > 0.12) failures.push(`${file}: motor ${m.number} distance differs`);
        const spin = m.kind === "servo" ? "servo" : m.spin;
        if (spin !== d.spin) failures.push(`${file}: motor ${m.number} spin ${spin} vs ${d.spin}`);
        if (String(m.cant) !== String(d.cant)) failures.push(`${file}: motor ${m.number} cant ${m.cant} vs ${d.cant}`);
        const twin = [...drawn.values()].some((o) => o !== d && Math.abs(o.x - d.x) < 1 && Math.abs(o.y - d.y) < 1);
        if (twin && (d.layer === "top" || d.layer === "bottom")) m.stack = d.layer;
    }
    checkFrameLines(file, layout.frameLines, layout.motors, drawn, failures);
}

/**
 * The frame lines the renderer will draw — `frameLines` where ArduPilot gives
 * them, else a spoke from the center to every mark, exactly as
 * `append_frame()` does — must be the lines the official diagram draws.
 * Compared as unordered, undirected segments after scaling ours into the
 * diagram's units via the farthest motor.
 */
function checkFrameLines(file, frameLines, marks, drawn, failures) {
    const drawnLines = parseFrameLines(file);
    const far = marks.reduce((a, b) => (Math.hypot(b.x, b.y) > Math.hypot(a.x, a.y) ? b : a));
    const d = drawn.get(String(far.number ?? far.label));
    const scale = Math.hypot(d.x, d.y) / Math.hypot(far.x, far.y);
    const ours = (frameLines ?? marks.map((m) => [0, 0, m.x, m.y]))
        .map(([x1, y1, x2, y2]) => [x1 * scale, -y1 * scale, x2 * scale, -y2 * scale]);
    const same = (a, b) => {
        const close = (p, q) => Math.abs(p - q) < 2;
        return (close(a[0], b[0]) && close(a[1], b[1]) && close(a[2], b[2]) && close(a[3], b[3]))
            || (close(a[0], b[2]) && close(a[1], b[3]) && close(a[2], b[0]) && close(a[3], b[1]));
    };
    for (const line of ours) if (!drawnLines.some((l) => same(l, line))) failures.push(`${file}: frame line ${line.map((n) => n.toFixed(0)).join(",")} isn't in the diagram`);
    for (const line of drawnLines) if (!ours.some((l) => same(l, line))) failures.push(`${file}: diagram line ${line.map((n) => n.toFixed(0)).join(",")} isn't drawn`);
}

/*
 * Drawings for the frame classes with no MotorN layout, so Frame Setup can
 * draw every class with the same renderer. BiCopter comes from ArduPilot's
 * display JSON and is checked against its official diagram like the rest;
 * it runs on ThrottleLeft/Right and tilt functions, not MotorN. The helicopters
 * have no ArduPilot layout data at all — they're schematic, not a claim about
 * where anything is (see "Ambiguities" in motorLayouts.ts).
 */
const bi = display.layouts.find((l) => l.Class === 10);
const schematics = [
    {
        cls: 10,
        typeName: "BiCopter",
        source: "AP_Motors_display.json",
        marks: bi.motors.map((m) => ({kind: "motor", label: m.Number, x: round(-m.Roll), y: round(m.Pitch), spin: normalizeSpin(m.Rotation)})),
    },
    // UNVERIFIED: the three helicopter schematics below were drawn without
    // any ArduPilot layout data and haven't been checked by anyone who flies
    // helicopters. Used as-is until someone who does reviews them.
    {
        cls: 6,
        typeName: "Heli",
        source: "schematic",
        frameLines: [[0, 0, 0, -0.7]],
        marks: [
            {kind: "rotor", x: 0, y: 0, size: 0.5, spin: null},
            {kind: "motor", x: 0, y: -0.7, spin: "Either"},
        ],
    },
    {
        cls: 11,
        typeName: "Heli_Dual",
        source: "schematic",
        frameLines: [[0, 0.4, 0, -0.4]],
        marks: [
            {kind: "rotor", x: 0, y: 0.4, size: 0.36, spin: null},
            {kind: "rotor", x: 0, y: -0.4, size: 0.36, spin: null},
        ],
    },
    {
        cls: 13,
        typeName: "HeliQuad",
        source: "schematic",
        marks: [[0.5, 0.5], [-0.5, 0.5], [-0.5, -0.5], [0.5, -0.5]].map(([x, y]) => ({kind: "rotor", x, y, size: 0.24, spin: null})),
    },
];
{
    const bicopterImage = images.get(10)?.get(0);
    if (bicopterImage) {
        checked++;
        const drawn = parseDiagram(bicopterImage);
        const marks = schematics.find((s) => s.cls === 10).marks;
        for (const m of marks) {
            const d = drawn.get(m.label);
            if (!d) failures.push(`${bicopterImage}: no motor ${m.label}`);
            else if (Math.sign(d.x) !== Math.sign(m.x) || d.spin !== m.spin) failures.push(`${bicopterImage}: motor ${m.label} differs`);
        }
        checkFrameLines(bicopterImage, undefined, marks, drawn, failures);
    }
}
if (failures.length) {
    console.error(`${failures.length} layout(s) disagree with the bundled diagrams — nothing written:\n  ${failures.join("\n  ")}`);
    // exitCode rather than exit(): exiting with fetch's sockets still closing
    // trips a libuv assertion on Windows.
    process.exitCode = 1;
} else {
    writeLayouts();
}

function writeLayouts() {

const sorted = [...layouts.values()].sort((a, b) => a.cls - b.cls || a.type - b.type);
const out = {
    source: [`${WIKI}/AP_Motors_test.json (${test.Version})`, `${WIKI}/AP_Motors_display.json`, "data/frames/*.svg (stacking order, validation)"],
    fetchedAt: new Date().toISOString().slice(0, 10),
    defaultTypeClasses: [...DEFAULT_TYPE_CLASSES],
    layouts: sorted.filter((l) => !DEFAULT_TYPE_CLASSES.has(l.cls) || l.type === 0 || l.typeName.toLowerCase() !== "default"),
    schematics,
};
    mkdirSync(join(ROOT, "src", "lib", "frames"), {recursive: true});
    writeFileSync(OUT, JSON.stringify(out, null, 1) + "\n");
    console.log(`${out.layouts.length} layouts written, ${checked} checked against their diagrams, 0 disagreements.`);
}
